# idea: winsorized log-mel + per-sample rank + three narrow RFF banks at complementary bandwidths
"""
Untrained encoder for iEEG high-gamma from the 40-band time-averaged log-mel stimulus vector.

Five concatenated per-sample, deterministic blocks:
  1) hard winsorization of the raw bands to [-2.25, 0]  (kills drifting extreme-band noise);
  2) per-sample rank of the 40 bands rescaled to [0,1]  (loudness-offset-invariant relative shape);
  3) primary  RFF bank sqrt(2/D1)*cos(X@W1+b1), D1=64, W1~N(0,1/2.0^2), scale 0.5, seed 1;
  4) secondary RFF bank sqrt(2/D2)*cos(X@W2+b2), D2=16, W2~N(0,1/3.0^2), scale 0.4, seed 14;
  5) tertiary  RFF bank sqrt(2/D3)*cos(X@W3+b3), D3=16, W3~N(0,1/1.0^2), scale 0.3, seed 0.
Winsor + rank form the generalization backbone (train_r ~0.18 alone); the three narrow, down-scaled
RFF banks at complementary bandwidths (fine 1.0, mid 2.0, coarse 3.0) hedge the unknown spectral
kernel and add nonlinear structure the ridge can selectively recruit. D_out = 40 + 40 + 64 + 16 + 16
= 176. Everything is fixed-seed random or analytic, per-sample, never trained.
"""
import math
import torch


class Model:
    name = "winsor+rank+3-bank-RFF"
    idea = "winsorized log-mel + per-sample rank + three narrow RFF banks at complementary bandwidths"
    description = (
        "Given the 40-band time-averaged log-mel vector per word, concatenate five per-sample blocks: "
        "(a) hard winsorization to [-2.25, 0]; (b) per-sample rank scaled to [0,1] (loudness-offset "
        "invariant shape); (c) sqrt(2/64)*cos(X@W1+b1), W1~N(0, 1/2^2), scale 0.5; (d) sqrt(2/16)*"
        "cos(X@W2+b2), W2~N(0, 1/3^2), scale 0.4; (e) sqrt(2/16)*cos(X@W3+b3), W3~N(0, 1/1^2), "
        "scale 0.3. All (W_i, b_i) fixed-seed. D_out=176; never trained, per-sample only.")
    insight = (
        "Winsor+rank alone (D=80, train_r 0.18) already beat the raw log-mel floor by exploiting the "
        "temporal-drift-invariant spectral shape. Adding ONE narrow down-scaled RFF bank pushed test_r "
        "to 0.077 (train_r 0.26); adding a SECOND and THIRD bank at complementary bandwidths (fine + "
        "mid + coarse) lifts test_r to ~0.084 without letting train_r explode (~0.28). Multi-bandwidth "
        "hedges the unknown spectral kernel, and the down-scaling keeps the ridge anchored on the "
        "generalization backbone rather than any single bank. Next: search for more per-sample "
        "generalization primitives, or replace the outer bandwidth (sig=1) with a structured wavelet.")

    # Primary + two auxiliary RFF banks
    D1, SIG1, SC1, SEED1 = 64, 2.0, 0.5, 1
    D2, SIG2, SC2, SEED2 = 16, 3.0, 0.4, 14
    D3, SIG3, SC3, SEED3 = 16, 1.0, 0.3, 0
    WIN_LO, WIN_HI = -2.25, 0.0

    def __init__(self):
        self._banks = None
        self.n_params = 0

    def _build_bank(self, d_in, D, sigma, seed, device):
        gW = torch.Generator(device="cpu").manual_seed(seed)
        gb = torch.Generator(device="cpu").manual_seed(seed + 1)
        W = torch.randn(d_in, D, generator=gW) / sigma
        b = torch.rand(D, generator=gb) * (2 * math.pi)
        return W.to(device), b.to(device)

    def _build(self, d_in, device):
        self._banks = [
            (*self._build_bank(d_in, self.D1, self.SIG1, self.SEED1, device), self.D1, self.SC1),
            (*self._build_bank(d_in, self.D2, self.SIG2, self.SEED2, device), self.D2, self.SC2),
            (*self._build_bank(d_in, self.D3, self.SIG3, self.SEED3, device), self.D3, self.SC3),
        ]
        self.n_params = sum(W.numel() + b.numel() for W, b, _, _ in self._banks)

    @torch.no_grad()
    def __call__(self, X):
        X = torch.as_tensor(X).reshape(X.shape[0], -1).float()
        d_in = X.shape[1]
        if self._banks is None or self._banks[0][0].shape[0] != d_in or self._banks[0][0].device != X.device:
            self._build(d_in, X.device)
        wins = X.clamp(self.WIN_LO, self.WIN_HI)
        rnk = X.argsort(dim=1).argsort(dim=1).float() / (d_in - 1)
        parts = [wins, rnk]
        for W, b, D, sc in self._banks:
            parts.append(sc * math.sqrt(2.0 / D) * torch.cos(X @ W + b))
        return torch.cat(parts, dim=1)


MODEL = Model()
